def shlex_split(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        # Skip whitespace
        if c in (' ', '\t', '\n', '\r', '\f', '\v'):
            i += 1
            continue
        # Start a new token
        token = []
        while i < n:
            c = s[i]
            if c in (' ', '\t', '\n', '\r', '\f', '\v'):
                break
            elif c == '\\':
                # Backslash outside quotes: escape next char
                if i + 1 < n:
                    token.append(s[i + 1])
                    i += 2
                else:
                    # Trailing backslash: literal
                    token.append('\\')
                    i += 1
            elif c == "'":
                # Single quote: everything literal until next single quote
                i += 1
                while i < n and s[i] != "'":
                    token.append(s[i])
                    i += 1
                if i < n:
                    i += 1  # skip closing quote
                # else: unterminated, just stop
            elif c == '"':
                # Double quote: backslash escapes only \ or "
                i += 1
                while i < n and s[i] != '"':
                    c2 = s[i]
                    if c2 == '\\' and i + 1 < n and s[i + 1] in ('"', '\\'):
                        token.append(s[i + 1])
                        i += 2
                    else:
                        token.append(c2)
                        i += 1
                if i < n:
                    i += 1  # skip closing quote
            else:
                token.append(c)
                i += 1
        tokens.append(''.join(token))
    return tokens
