def shlex_split(s):
    """
    Reproduce shlex.split(s) in POSIX mode from scratch.

    Handles:
    - Whitespace splitting
    - Single quotes (everything literal inside, no escapes)
    - Double quotes (backslash escapes only another backslash or double quote, otherwise literal)
    - Backslash escaping outside quotes
    - Adjacent quoted and unquoted runs concatenating into one token
    """
    tokens = []
    current_token = []
    in_single_quote = False
    in_double_quote = False
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if in_single_quote:
            if c == "'":
                in_single_quote = False
                i += 1
            else:
                current_token.append(c)
                i += 1
        elif in_double_quote:
            if c == '\\':
                if i + 1 < n:
                    next_c = s[i + 1]
                    if next_c == '\\' or next_c == '"':
                        current_token.append(next_c)
                        i += 2
                    else:
                        # Backslash is literal in this case
                        current_token.append(c)
                        i += 1
                else:
                    # Trailing backslash in double quotes
                    current_token.append(c)
                    i += 1
            elif c == '"':
                in_double_quote = False
                i += 1
            else:
                current_token.append(c)
                i += 1
        else:
            # Not in any quote
            if c == "'":
                in_single_quote = True
                i += 1
            elif c == '"':
                in_double_quote = True
                i += 1
            elif c == '\\':
                if i + 1 < n:
                    current_token.append(s[i + 1])
                    i += 2
                else:
                    # Trailing backslash
                    current_token.append(c)
                    i += 1
            elif c.isspace():
                if current_token:
                    tokens.append(''.join(current_token))
                    current_token = []
                i += 1
            else:
                current_token.append(c)
                i += 1

    # If we end inside a quote, that's an error in shlex, but let's just handle it
    if in_single_quote or in_double_quote:
        raise ValueError("No closing quotation")

    if current_token:
        tokens.append(''.join(current_token))

    return tokens
